import { Download } from "lucide-react";
import { cn } from "@/lib/utils";

// Spec sheets live in public/downloads and are generated by scripts/spec-sheets;
// the product catalogue is generated by scripts/catalogue.
export const specSheets = {
  catalogue: { href: "/downloads/vyro-product-catalogue.pdf", label: "Product catalogue" },
  glacier: { href: "/downloads/vyro-glacier-spec-sheet.pdf", label: "Glacier spec sheet" },
  haven: { href: "/downloads/vyro-haven-spec-sheet.pdf", label: "Haven sauna spec sheet" },
} as const;

export function DownloadLink({ sheet, className }: { sheet: keyof typeof specSheets; className?: string }) {
  const { href, label } = specSheets[sheet];
  return (
    <a
      href={href}
      download
      className={cn(
        "inline-flex items-center gap-2 text-[12px] uppercase tracking-[0.16em] underline decoration-bronze underline-offset-8 hover:text-bronze-strong",
        className,
      )}
    >
      <Download className="h-4 w-4" aria-hidden />
      {label} (PDF)
    </a>
  );
}
